//! indexed_zk prove DIR N GROUPS GATES GAMMA | indexed_zk verify DIR
//! Correctness executions only: no comparative full-SNARK performance claim.
use b2proto::{indexed,indexed_codec as codec,sha_zk::Config,field::{L,Field}};
use std::{fs,path::Path,time::Instant};
fn main(){let args:Vec<_>=std::env::args().skip(1).collect();let dir=Path::new(&args[1]);
 if args[0]=="verify"{let start=Instant::now();let vk=codec::decode_key(&fs::read(dir.join("key.bin")).unwrap()).unwrap();let load=start.elapsed().as_secs_f64();let b=fs::read(dir.join("statement.bin")).unwrap();assert_eq!(b.len(),vk.batch()*32);let d:Vec<_>=b.chunks_exact(32).map(|x|x.try_into().unwrap()).collect();let p=fs::read(dir.join("proof.bin")).unwrap();let(core,m)=codec::decode_proof(&vk,&p).unwrap();let check=Instant::now();indexed::verify(&vk,&d,&core,&m).unwrap();println!("{{\"verified\":true,\"independent_process\":true,\"key_load_s\":{load},\"verify_s\":{},\"proof_bytes\":{},\"circuit_or_index_loaded\":false}}",check.elapsed().as_secs_f64(),p.len());return;}
 assert_eq!(args.len(),6);assert_eq!(args[0],"prove");assert!(!dir.exists());fs::create_dir_all(dir).unwrap();let n=args[2].parse().unwrap();let groups=args[3].parse().unwrap();let gates=args[4].parse().unwrap();let gamma=args[5].parse().unwrap();let start=Instant::now();let cfg=Config::synthetic(n,groups,gamma,3,gates);let index=indexed::Index::new(&cfg,gamma);let vk=index.verifier_key(&cfg);let setup=start.elapsed().as_secs_f64();let nnz=index.private.entries.len()+index.public.entries.len();let rows=cfg.circuit.base.m0()*cfg.batch();let slots=cfg.circuit.private_len*cfg.batch();let index_cells=index.private.committed.values.len()+index.public.committed.values.len()+index.private.final_committed.values.len()+index.public.final_committed.values.len();
 let(run,m)=indexed::prove(&cfg,&index,21);let coretime=run.times.total.as_secs_f64();let proof=codec::encode_proof(&run.proof,&m);let key=codec::encode_key(&vk);fs::write(dir.join("proof.bin"),&proof).unwrap();fs::write(dir.join("key.bin"),&key).unwrap();fs::write(dir.join("statement.bin"),run.digests.iter().flatten().copied().collect::<Vec<_>>()).unwrap();drop(index);drop(cfg);
 let vk=codec::decode_key(&key).unwrap();let(core,mat)=codec::decode_proof(&vk,&proof).unwrap();indexed::verify(&vk,&run.digests,&core,&mat).unwrap();
 let mut rejected=0;let mut bad=mat.clone();bad.weight+=L::ONE;rejected+=indexed::verify(&vk,&run.digests,&core,&bad).is_err() as usize;
 let mut bad=mat.clone();bad.public_value+=L::ONE;rejected+=indexed::verify(&vk,&run.digests,&core,&bad).is_err() as usize;
 let mut bad=mat.clone();bad.private.opening.openings[0][0].path[0][0]^=1;rejected+=indexed::verify(&vk,&run.digests,&core,&bad).is_err() as usize;
 let mut bad=core.clone();bad.nonce[0]^=1;rejected+=indexed::verify(&vk,&run.digests,&bad,&mat).is_err() as usize;
 let mut d=run.digests.clone();d[0][0]^=1;rejected+=indexed::verify(&vk,&d,&core,&mat).is_err() as usize;
 let mut k=codec::decode_key(&key).unwrap();k.public.pcs.root[0]^=1;rejected+=indexed::verify(&k,&run.digests,&core,&mat).is_err() as usize;
 let mut trailing=proof.clone();trailing.push(0);rejected+=codec::decode_proof(&vk,&trailing).is_err() as usize;rejected+=codec::decode_proof(&vk,&proof[..proof.len()-1]).is_err() as usize;assert_eq!(rejected,8);
 println!("{{\"verified\":true,\"internal_hash\":\"blake3\",\"N\":{n},\"groups\":{groups},\"gates_per_copy_before_masks\":{gates},\"gamma\":{gamma},\"rows_with_masks_and_padding\":{rows},\"private_bit_slots\":{slots},\"matrix_nnz_common_slots\":{nnz},\"index_field_cells\":{index_cells},\"index_setup_s\":{setup},\"prove_and_verify_s\":{coretime},\"proof_bytes\":{},\"public_matrix_proof_bytes\":{},\"key_bytes\":{},\"negative_checks_passed\":{rejected}}}",proof.len(),m.encode().len(),key.len());
}
